// Authentic ZX Spectrum 48K, 128K, +2, Pentagon 128, TR-DOS 5.03/6.04 & Scorpion ZS-256 ROMs

function b64ToBytes(b64: string): Uint8Array {
  if (typeof atob === "function") {
    const bin = atob(b64);
    const arr = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    return arr;
  }
  return new Uint8Array(Buffer.from(b64, "base64"));
}

const ROM_B64 = {
  rom48: "",
  rom128_0: "",
  rom128_1: "",
  romPlus2_0: "",
  romPlus2_1: "",
  romPentagon: "",
  romTrdos503: "",
  romTrdos604: "",
  romScorp0: "",
  romScorp1: "",
  romScorp2: "",
  romScorp3: "",
} as const;

export type RomKey = keyof typeof ROM_B64;
const cache = new Map<RomKey, Uint8Array>();

export function getRomBytes(key: RomKey): Uint8Array {
  let cached = cache.get(key);
  if (!cached) {
    cached = b64ToBytes(ROM_B64[key]);
    cache.set(key, cached);
  }
  return new Uint8Array(cached);
}
